<?php
require_once __DIR__.'/../config/config.php';require_login();
$profile=permission_profile();if(!in_array($profile,['mis','doctor','nurse'],true)||!has_permission($profile==='mis'?'manage_users':'clinical_records_read'))admin_access_denied('Authorized reporting access required.');
$pageTitle='Report Exports';
?>
<!doctype html><html lang="en"><head><?php include __DIR__.'/../includes/head.php'; ?></head><body><div class="app-wrapper"><?php include __DIR__.'/../components/sidebar.php'; ?><div class="main-content"><?php include __DIR__.'/../components/navbar.php'; ?><main class="content-area" id="mainContent"><section class="card p-4"><h1 class="h4">CSV and Excel reports</h1><p>Download only authorized report fields. These reports are separate from MIS database recovery backups. Keep exported clinical records within authorized school storage.</p><p>Inventory exports show the current stock snapshot through the selected end date; they do not reconstruct historical balances.</p><form id="exportForm" class="row g-3"><?=csrf_field()?><div class="col-12"><label class="form-label" for="export-type">Report</label><select id="export-type" name="type" class="form-select"><?php foreach($profile==='mis'?['accounts'=>'Account inventory']:['consultations'=>'Patient consultation records','queue'=>'Queue summary (no patient names)','inventory'=>'Current medicine inventory'] as $value=>$label): ?><option value="<?=$value?>"><?=$label?></option><?php endforeach; ?></select></div><?php foreach(['from'=>'From','to'=>'Through'] as $field=>$label): ?><div class="col-12 col-md-6"><label class="form-label" for="export-<?=$field?>"><?=$label?></label><input class="form-control" type="date" id="export-<?=$field?>" name="<?=$field?>" value="<?=date($field==='from'?'Y-m-01':'Y-m-d')?>" required></div><?php endforeach; ?><div class="col-12"><label class="form-label" for="export-format">Format</label><select name="format" id="export-format" class="form-select"><option value="csv">UTF-8 CSV</option><option value="xlsx">Excel (.xlsx)</option></select></div><div class="col-12"><button class="btn btn-success">Download report</button></div><p id="export-status" role="status" aria-live="polite"></p></form></section></main></div></div><?php include __DIR__.'/../components/footer.php'; ?>
<script>document.getElementById('exportForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button'),status=document.getElementById('export-status');button.disabled=true;status.textContent='Preparing authorized report…';try{const response=await fetch(<?=json_encode(app_url('api/report_exports.php'))?>,{method:'POST',body:new FormData(form)});if(!response.ok){const body=await response.json();throw new Error(body.message||'Export failed.');}const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='clinic-'+form.elements.type.value+'.'+form.elements.format.value;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='Report downloaded.';}catch(error){status.textContent=error.message||'Report unavailable. Please retry.';}finally{button.disabled=false;}});</script></body></html>
